import AppKit

/// Traced panel and new-document glyphs. Coordinates are points, y down,
/// measured from the comparison crop. Reference pixels are not shipped.
enum TracedMarks {
    static func path(_ name: String) -> NSBezierPath? {
        guard let packed = catalog[name] else { return nil }
        return TracedPath.make(packed)
    }

    static func draw(_ name: String, origin: NSPoint, color: NSColor) {
        guard let path = path(name) else { return }
        let moved = AffineTransform(translationByX: -origin.x, byY: -origin.y)
        path.transform(using: moved)
        color.setFill()
        path.fill()
    }

    /// Detail column is not flipped: crop y grows downward from detailTop.
    static func drawDetail(_ name: String, left: CGFloat, top: CGFloat, color: NSColor) {
        guard let path = path(name) else { return }
        path.transform(using: AffineTransform(scaleByX: 1, byY: -1))
        path.transform(using: AffineTransform(translationByX: left, byY: top))
        color.setFill()
        path.fill()
    }

